static ge::graphStatus TilingFunc(gert::TilingContext* context)
{
    auto in0 = context->GetInputShape(0);  // x: [N, K]
    auto in1 = context->GetInputShape(1);  // weight: [K, M]
    if (in0 == nullptr || in1 == nullptr) {
        return ge::GRAPH_FAILED;
    }

    uint32_t n = static_cast<uint32_t>(in0->GetOriginShape().GetDim(0));
    uint32_t k = static_cast<uint32_t>(in0->GetOriginShape().GetDim(1));
    uint32_t k_w = static_cast<uint32_t>(in1->GetOriginShape().GetDim(0));
    uint32_t m = static_cast<uint32_t>(in1->GetOriginShape().GetDim(1));
    if (k != k_w) {
        return ge::GRAPH_FAILED;
    }

    int64_t num_groups_attr = 0;
    (void)context->GetAttr("num_groups", num_groups_attr);
    uint32_t numGroups = static_cast<uint32_t>(num_groups_attr);

    context->SetBlockDim(BLOCK_DIM);

    MatmulSwishSumGroupNormCustomTilingData tiling;
    tiling.set_n(n);
    tiling.set_k(k);
    tiling.set_m(m);
    tiling.set_numGroups(numGroups);
